message.content:
{
  "title": "the torn banner rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party reaches the ruined outer gate.",
      "visual_description": "A crumbling stone gate flanked by broken statues, with a faded royal banner hanging limp in the still air.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople scatter at the patrol's horn.",
      "visual_description": "Narrow market street lined with shuttered stalls; citizens flee as a distant horn echoes between cracked walls.",
      "characters": ["map_reader", "scout", "magic_helper", "frightened_townsfolk"]
    },
    {
      "scene_number": 3,
      "caption": "The party hides from an armored patrol.",
      "visual_description": "Three soldiers in dented plate armor march past a collapsed fountain, their halberds glinting in pale sunlight.",
      "characters": ["map_reader", "scout", "magic_helper", "armored_patrol"]
    },
    {
      "scene_number": 4,
      "caption": "The scout spots the cursed tower.",
      "visual_description": "A leaning spire wrapped in thorny vines, its peak crowned with a swirling amber storm cloud.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 5,
      "caption": "Rumors of a dragon stir among the ruins.",
      "visual_description": "Crumbled temple interior where a frightened townsman points upward, a charred shadow on the ceiling above.",
      "characters": ["map_reader", "scout", "magic_helper", "frightened_townsfolk"]
    },
    {
      "scene_number": 6,
      "caption": "The magic helper reads an old door.",
      "visual_description": "A massive stone door carved with glowing runes; the magic helper traces a symbol while the scout keeps watch.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 7,
      "caption": "The door opens into a mirror hall.",
      "visual_description": "Long corridor lined with cracked mirrors reflecting distorted versions of the party members.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 8,
      "caption": "A reflection trap nearly splits the group.",
      "visual_description": "The scout's reflection steps out of a mirror; the magic helper shatters it with a crystal shard.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 9,
      "caption": "They find the rescue target in a throne room.",
      "visual_description": "Broken throne under a stained-glass window; a bound figure sits on the dais, a torn banner draped over their shoulders.",
      "characters": ["map_reader", "scout", "magic_helper", "rescued_prisoner"]
    },
    {
      "scene_number": 10,
      "caption": "The magic helper picks the lock with a crystal key.",
      "visual_description": "Close view of shackles on the prisoner's wrists; the crystal key glows as it turns in the lock.",
      "characters": ["magic_helper", "rescued_prisoner"]
    },
    {
      "scene_number": 11,
      "caption": "Armored patrols block the main exit.",
      "visual_description": "Throne room doors burst open to reveal a row of shields and halberds filling the doorway.",
      "characters": ["map_reader", "scout", "magic_helper", "rescued_prisoner", "armored_patrol"]
    },
    {
      "scene_number": 12,
      "caption": "The scout leads a retreat through a servant passage.",
      "visual_description": "Narrow stone staircase spiraling downward, cobwebs brushing the party's heads as they hurry.",
      "characters": ["map_reader", "scout", "magic_helper", "rescued_prisoner"]
    },
    {
      "scene_number": 13,
      "caption": "The passage opens into an old plaza.",
      "visual_description": "Sunken plaza with a dry fountain in the center, surrounded by collapsed colonnades and mossy paving stones.",
      "characters": ["map_reader", "scout", "magic_helper", "rescued_prisoner"]
    },
    {
      "scene_number": 14,
      "caption": "A dragon's shadow passes overhead.",
      "visual_description": "Winged silhouette gliding across the plaza floor; everyone freezes as the shadow slides past.",
      "characters": ["map_reader", "scout", "magic_helper", "rescued_prisoner"]
    },
    {
      "scene_number": 15,
      "caption": "The magic helper shields the group from a blast.",
      "visual_description": "A column of fire from above meets a shimmering dome held by the magic helper's outstretched hands.",
      "characters": ["map_reader", "scout", "magic_helper", "rescued_prisoner"]
    },
    {
      "scene_number": 16,
      "caption": "The party reaches the bridge controls.",
      "visual_description": "Stone lever mechanism on a platform overlooking a chasm; the bridge lies retracted on the far side.",
      "characters": ["map_reader", "scout", "magic_helper", "rescued_prisoner"]
    },
    {
      "scene_number": 17,
      "caption": "The map reader pulls the lever to extend the bridge.",
      "visual_description": "Heavy lever grinding downward as chains rattle and the bridge begins to swing across the gap.",
      "characters": ["map_reader", "scout", "magic_helper", "rescued_prisoner"]
    },
    {
      "scene_number": 18,
      "caption": "They escape across the bridge as the city crumbles behind.",
      "visual_description": "The party runs over the wooden bridge, the ruined city smoking and collapsing in the distance under a dragon's circling flight.",
      "characters": ["map_reader", "scout", "magic_helper", "rescued_prisoner"]
    }
  ]
}

